import{_ as a,c as t,o,ae as s}from"./chunks/framework.DEXG3EuZ.js";const h=JSON.parse('{"title":"UI Framework Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/ui-framework.md","filePath":"en/guide/ui-framework.md","lastUpdated":1792605191000}'),n={name:"en/guide/ui-framework.md"};function i(r,e,c,d,l,p){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="ui-framework-strategy" tabindex="-1">UI Framework Strategy <a class="header-anchor" href="#ui-framework-strategy" aria-label="Permalink to &quot;UI Framework Strategy&quot;">​</a></h1><p>The template retains Vant, NutUI, and Varlet as choices, while each production build selects exactly one:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VITE_UI_FRAMEWORK=vant</span></span></code></pre></div><p>Vite selects the matching resolver, SCSS injection, and <code>#ui-demo</code> alias. Business code has no scattered framework conditionals, and the other packages do not enter the current production graph.</p><p>Core Layout, AI Chat, and engineering examples use lightweight template styles and <code>SvgIcon</code> to avoid cross-framework coupling. Real projects should select one UI library during initialization; a future CLI can remove unselected dependencies.</p><h2 id="svg-icons" tabindex="-1">SVG Icons <a class="header-anchor" href="#svg-icons" aria-label="Permalink to &quot;SVG Icons&quot;">​</a></h2><p>Place product icons in <code>src/assets/icons/*.svg</code>. The plugin creates a sprite and the app uses typed <code>&lt;SvgIcon name=&quot;ai&quot; /&gt;</code>. Keep framework-provided icons local to that framework and outside the product icon union.</p><h2 id="styling" tabindex="-1">Styling <a class="header-anchor" href="#styling" aria-label="Permalink to &quot;Styling&quot;">​</a></h2><p>Global design tokens live in <code>src/styles/index.scss</code>; component layouts use scoped SCSS. UnoCSS was not added because the current project does not need a second atomic styling paradigm. The viewport plugin converts business px values from a 750 design width and treats UI libraries as 375. Verify final 44 CSS-pixel touch targets, safe-area, dark scheme, and focus-visible behavior.</p>',9)])])}const g=a(n,[["render",i]]);export{h as __pageData,g as default};
